// 🟢 3. PARSE RSS ITEMS
const itemBlocks = rawXml.match(/<item>([\s\S]*?)<\/item>/g) || [];
const articles = itemBlocks.map(item => {
  let title = '';
  const cdataTitle = item.match(/<title><!\[CDATA\[([^\]]+)\]\]><\/title>/);
  const plainTitle = item.match(/<title>([^<]+)<\/title>/);
  title = (cdataTitle ? cdataTitle[1] : (plainTitle ? plainTitle[1] : '')).trim();
  const link = (item.match(/<link>([^<]+)<\/link>/) || [])[1] || '';
  const descRaw = (item.match(/<description>([\s\S]*?)<\/description>/) || [])[1] || '';
  return { title, description: descRaw.replace(/<[^>]*>/g,' ').trim().substring(0,500), link };
});

// 🟢 4. DEDUPLICATION LOGIC (STRICT)
function isDuplicate(title) {
  const t = title.toLowerCase().trim();
  const s = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').trim();

  // Check against WordPress
  const isWpDupe = wpTitles.some(et => et === t || et.includes(t)) || 
                   wpSlugs.some(es => es === s || es.includes(s));

  // Check against Local Memory (History)
  const isLocalDupe = localBlacklist.some(lt => lt === t || t.includes(lt));

  return isWpDupe || isLocalDupe;
}

// 🟢 5. SELECTION PROCESS
const fresh = articles.filter(a => a.title.length > 10 && !isDuplicate(a.title));
let selected, source;

if (fresh.length > 0) {
  // Pick a random fresh one from RSS
  selected = fresh[Math.floor(Math.random() * fresh.length)];
  source = 'rss_fresh';
} else {
  // Fallback to MASSIVE POOL
  const pool = FALLBACK_POOL[currentCategoryId] || FALLBACK_POOL["1"];
  const freshPool = pool.filter(f => !isDuplicate(f.title));

  if (freshPool.length > 0) {
    // Pick first available unique fallback
    selected = freshPool[0];
    source = 'fallback_evergreen';
  } else {
    // 🔴 KILL SWITCH: Absolutely no fresh content
    return { json: { _error: "NO_FRESH_TOPICS_AVAILABLE", _stop: true } };
  }
}

// 🟢 6. UPDATE LOCAL MEMORY (Keep last 50)
staticData.usedTopics.push(selected.title);
if (staticData.usedTopics.length > 50) staticData.usedTopics.shift();

return [{ json: {
