  category_id: forcedCatId,
  slug: topicTitle.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').substring(0,60),
  metaDescription: `Discover professional recipes and cooking tips for ${topicTitle} on texasdadcooks.com.`,
  excerpt: `Essential guide to ${topicTitle} with food science tips and historical context.`,
  tags: [topicFirst.replace(/\s+/g,','),'recipes','cooking','food','kitchen'],
  imgQuery1: topicFirst + ' food cooking recipe',
  imgQuery2: topicFirst + ' meal dish plate',
  imgQuery3: topicFirst + ' ingredients kitchen fresh',
  _hasContent: false,
  _error: true
