const createCleanSlug = (text) => {
  if (!text) return '';
  let s = text.toLowerCase()
    .replace(/[^a-z0-9\s-]/g, '') // remove special chars
    .replace(/\s+/g, '-')         // spaces to hyphens
    .replace(/-+/g, '-')         // collapse multiple hyphens
    .replace(/-(complete|recipe|guide|ready|in|minutes|easy|simple|expert|cooking|best|homemade|delicious)-/g, '-') // remove filler
    .replace(/-(complete|recipe|guide|ready|in|minutes|easy|simple|expert|cooking|best|homemade|delicious)$/g, '')
    .replace(/^-|-$/g, '');       // trim hyphens

  if (s.length > 65) {
    const lastDash = s.lastIndexOf('-', 65);
    if (lastDash > 20) s = s.substring(0, lastDash);
    else s = s.substring(0, 65);
  }
  return s.replace(/-$/g, '');
};

// ============================================
