const raw = ($json.candidates?.[0]?.content?.parts?.[0]?.text) || ($json.choices?.[0]?.message?.content) || '';
const trendData = $('Format Categories for Gemini').first().json;
const topicFallback = trendData.trendingTopic || 'Easy Cooking Recipes';
