}

const lines = raw.split('\n');
let title='', slug='', categoryId=forcedCatId, metaDesc='', tagsRaw='', excerpt='', imgQ1='', imgQ2='', imgQ3='';
let articleStart = -1;

for (let i = 0; i < lines.length; i++) {
  const t = lines[i].trim();
  if (t.startsWith('TITLE:'))    title    = t.slice(6).trim();
  if (t.startsWith('CATEGORY:')) { /* IGNORE Gemini's category — we use forced category */ }
  if (t.startsWith('SLUG:'))     slug     = createCleanSlug(t.slice(5).trim());
  if (t.startsWith('META:'))     metaDesc = t.slice(5).trim().substring(0,155);
  if (t.startsWith('TAGS:'))     tagsRaw  = t.slice(5).trim();
  if (t.startsWith('EXCERPT:'))  excerpt  = t.slice(8).trim();
  if (t.startsWith('QUERY1:'))   imgQ1    = t.slice(7).trim();
  if (t.startsWith('QUERY2:'))   imgQ2    = t.slice(7).trim();
  if (t.startsWith('QUERY3:'))   imgQ3    = t.slice(7).trim();
  if (t.startsWith('WIKI_TOPIC:')) { /* consume and discard wiki topic metadata */ }
  if (t.includes('START===')) { articleStart = i + 1; break; }
}

// ALWAYS use the forced category from round-robin — NEVER Gemini's choice
categoryId = forcedCatId;

if (articleStart === -1) {
  const q3Idx = lines.findIndex(l => l.includes('QUERY3:'));
  if (q3Idx !== -1) articleStart = q3Idx + 1;
}

let articleHTML = '';
if (articleStart >= 0) {
  const rest = lines.slice(articleStart);
  const endIdx = rest.findIndex(l => l.includes('END==='));
  articleHTML = (endIdx >= 0 ? rest.slice(0, endIdx) : rest).join('\n').trim();
} else {
  articleHTML = raw;
}
articleHTML = articleHTML.replace(/^```html\s*/i,'').replace(/^```\s*/,'').replace(/```\s*$/,'').trim();

// Strip leaked WIKI_TOPIC metadata and Wikipedia/Wikimedia mentions
articleHTML = articleHTML.replace(/^\s*WIKI_TOPIC:.*$/gm, '').trim();
articleHTML = articleHTML.replace(/\([^)]*(?:Wikipedia|Wikimedia)[^)]*\)/gi, '');
articleHTML = articleHTML.replace(/,?\s*as (?:detailed|described|documented|noted|referenced|mentioned) (?:on|in|by|at|via) (?:Wikipedia|Wikimedia)[^.,;)]*[.,;)]?/gi, '');
articleHTML = articleHTML.replace(/,?\s*according to (?:Wikipedia|Wikimedia)[^.,;)]*[.,;)]?/gi, '');

// Convert markdown headers just in case Gemini ignored the HTML instruction
articleHTML = articleHTML.replace(/^###\s+(.+)$/gm, '<h3>$1</h3>');
