function pickBestImage(nodeName, matchKeywords) {
  try {
    const apiResponse = $(nodeName).first().json;
    const photos = (apiResponse && apiResponse.photos) ? apiResponse.photos : [];
    if (photos.length === 0) return null;
    const available = photos.filter(p => !usedImgIds.has(p.id));
    if (available.length === 0) return null;

    const keywords = (matchKeywords || articleTopic).toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(w => w.length > 2);
    const scored = available.map(p => {
      const text = ((p.alt || '') + ' ' + (p.url || '')).toLowerCase();
      let score = 0;
      for (const kw of keywords) { if (text.includes(kw)) score += 1; }
      return { photo: p, score };
    });
    scored.sort((a,b) => b.score - a.score);
    const pick = scored[0].photo;
    if (!pick) return null;
    usedImgIds.add(pick.id);

    return {
      url:   normalize(pick.src.original || pick.src.large2x),
      alt:   pick.alt || articleTopic,
      pName: pick.photographer || 'Pexels Photographer',
      pUrl:  pick.photographer_url,
      pgUrl: pick.url,
      source: 'pexels'
    };
  } catch(e) { return null; }
}

