const artData = $input.first().json;
const tags = artData.tags || [];
const wpBase = $('Build Config').item.json._wpBase;
const auth = $('Build Config').item.json._auth;
const tagIds = [];
for (const tagName of tags) {
  const slug = tagName.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
  try {
    const searchRes = await $http.get(`${wpBase}/wp-json/wp/v2/tags?search=${encodeURIComponent(tagName)}&per_page=5`, { headers: { 'Authorization': auth } });
    const existing = searchRes.data?.find(t => t.slug === slug || t.name.toLowerCase() === tagName.toLowerCase());
    if (existing) tagIds.push(existing.id);
    else {
      const createRes = await $http.post(`${wpBase}/wp-json/wp/v2/tags`, { name: tagName, slug }, { headers: { 'Authorization': auth, 'Content-Type': 'application/json' } });
      if (createRes.data?.id) tagIds.push(createRes.data.id);
    }
  } catch(e) { /* skip */ }
}
return [{ json: { ...artData, _tagIds: tagIds } }];
